add_action( 'add_meta_boxes', 'perfectpixel_extra_description_box' );
add_action( 'save_post_product', 'perfectpixel_extra_description_save' );
add_action( 'woocommerce_after_single_product_summary', 'perfectpixel_extra_description_output', 30 );

function perfectpixel_extra_description_box() {
	add_meta_box( 'perfectpixel_extra_description', '{{extra_description_title}}', 'perfectpixel_extra_description_editor', 'product', 'normal', 'low' );
}

function perfectpixel_extra_description_editor( $post ) {
	wp_nonce_field( 'perfectpixel_extra_description', 'perfectpixel_extra_description_nonce' );
	wp_editor( get_post_meta( $post->ID, '_perfectpixel_extra_description', true ), 'perfectpixel_extra_description', array( 'textarea_rows' => 8 ) );
}

function perfectpixel_extra_description_save( $post_id ) {
	if ( ! isset( $_POST['perfectpixel_extra_description_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['perfectpixel_extra_description_nonce'] ), 'perfectpixel_extra_description' ) ) {
		return;
	}
	if ( ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) || ! current_user_can( 'edit_post', $post_id ) ) {
		return;
	}
	$content = isset( $_POST['perfectpixel_extra_description'] ) ? wp_kses_post( wp_unslash( $_POST['perfectpixel_extra_description'] ) ) : '';
	update_post_meta( $post_id, '_perfectpixel_extra_description', $content );
}

function perfectpixel_extra_description_output() {
	$content = get_post_meta( get_the_ID(), '_perfectpixel_extra_description', true );
	if ( $content ) {
		echo '<div class="perfectpixel-extra-description" style="clear:both">' . wp_kses_post( wpautop( do_shortcode( $content ) ) ) . '</div>';
	}
}
